 62→type stuckSession struct {
 63→	State             *strategy.SessionState
 64→	Reason            string
 65→	ShadowBranch      string
 66→	HasShadowBranch   bool
 67→	CheckpointCount   int
 68→	FilesTouchedCount int
 69→}
