236→// displayStuckSession prints diagnostic info for a stuck session.
237→func displayStuckSession(cmd *cobra.Command, ss stuckSession) {
238→	w := cmd.OutOrStdout()
239→
240→	fmt.Fprintf(w, "  Session: %s\n", ss.State.SessionID)
241→	fmt.Fprintf(w, "  Phase:   %s\n", ss.State.Phase)
242→	fmt.Fprintf(w, "  Reason:  %s\n", ss.Reason)
243→
244→	if ss.State.AgentType != "" {
245→		fmt.Fprintf(w, "  Agent:   %s\n", ss.State.AgentType)
246→	}
247→
248→	if ss.State.LastInteractionTime != nil {
249→		fmt.Fprintf(w, "  Last interaction: %s\n", ss.State.LastInteractionTime.Format(time.RFC3339))
250→	}
251→
252→	shadowStatus := "not found"
253→	if ss.HasShadowBranch {
254→		shadowStatus = fmt.Sprintf("exists (%s)", ss.ShadowBranch)
255→	}
256→	fmt.Fprintf(w, "  Shadow branch: %s\n", shadowStatus)
257→	fmt.Fprintf(w, "  Checkpoints: %d, Files touched: %d\n", ss.CheckpointCount, ss.FilesTouchedCount)
258→}
