260→// promptSessionAction asks the user what to do with a stuck session.
261→func promptSessionAction(ss stuckSession) (string, error) {
262→	var action string
263→
264→	options := make([]huh.Option[string], 0, 3)
265→	if ss.HasShadowBranch && ss.CheckpointCount > 0 {
266→		options = append(options, huh.NewOption("Condense (save to permanent storage)", "condense"))
267→	}
268→	options = append(options,
269→		huh.NewOption("Discard (remove session data)", "discard"),
270→		huh.NewOption("Skip (leave as-is)", "skip"),
271→	)
272→
273→	form := NewAccessibleForm(
274→		huh.NewGroup(
275→			huh.NewSelect[string]().
276→				Title(fmt.Sprintf("Fix session %s?", ss.State.SessionID)).
277→				Options(options...).
278→				Value(&action),
279→		),
280→	)
281→
282→	if err := form.Run(); err != nil {
283→		return "", fmt.Errorf("session fix prompt failed: %w", err)
284→	}
285→
286→	return action, nil
287→}
