289→// discardSession removes session state and cleans up the shadow branch.
290→func discardSession(ctx context.Context, ss stuckSession, _ *git.Repository, errW io.Writer) error {
291→	// Clear session state file
292→	if err := strategy.ClearSessionState(ctx, ss.State.SessionID); err != nil {
293→		return fmt.Errorf("failed to clear session state: %w", err)
294→	}
295→
296→	// Delete shadow branch if it exists and no other sessions need it
297→	if ss.HasShadowBranch {
298→		if shouldDelete, err := canDeleteShadowBranch(ctx, ss.ShadowBranch, ss.State.SessionID); err != nil {
299→			fmt.Fprintf(errW, "Warning: could not check other sessions for shadow branch: %v\n", err)
300→		} else if shouldDelete {
301→			if err := strategy.DeleteBranchCLI(ctx, ss.ShadowBranch); err != nil {
302→				// Branch already gone is not an error — keeps discard idempotent
303→				if !errors.Is(err, strategy.ErrBranchNotFound) {
304→					return fmt.Errorf("failed to delete shadow branch: %w", err)
305→				}
306→			}
307→		}
308→	}
309→
310→	return nil
311→}
