313→// checkDisconnectedMetadata detects and optionally repairs disconnected
314→// local/remote metadata branches (the "empty-orphan bug").
315→func checkDisconnectedMetadata(cmd *cobra.Command, force bool) error {
316→	repo, err := openRepository(cmd.Context())
317→	if err != nil {
318→		return fmt.Errorf("failed to open repository: %w", err)
319→	}
320→
321→	ctx := cmd.Context()
322→	disconnected, err := strategy.IsMetadataDisconnected(ctx, repo)
323→	if err != nil {
324→		return fmt.Errorf("could not check metadata branch state: %w", err)
325→	}
326→
327→	w := cmd.OutOrStdout()
328→
329→	if !disconnected {
330→		fmt.Fprintln(w, "✓ Metadata branches: OK")
331→		return nil
332→	}
333→
334→	fmt.Fprintln(w, "Metadata branches: DISCONNECTED")
335→	fmt.Fprintln(w, "  Local and remote entire/checkpoints/v1 branches share no common ancestor.")
336→	fmt.Fprintln(w, "  Some remote checkpoints may not be visible locally.")
337→	fmt.Fprintln(w, "  Fix: cherry-pick local checkpoints onto remote tip (preserves all data).")
338→
339→	if !force {
340→		var confirmed bool
341→		form := NewAccessibleForm(
342→			huh.NewGroup(
343→				huh.NewConfirm().
344→					Title("Fix disconnected metadata branches?").
345→					Value(&confirmed),
346→			),
347→		)
348→		if formErr := form.Run(); formErr != nil {
349→			if errors.Is(formErr, huh.ErrUserAborted) {
350→				return nil
351→			}
352→			return fmt.Errorf("prompt failed: %w", formErr)
353→		}
354→		if !confirmed {
355→			fmt.Fprintln(w, "  -> Skipped")
356→			return nil
357→		}
358→	}
359→
360→	if fixErr := strategy.ReconcileDisconnectedMetadataBranch(ctx, repo, cmd.ErrOrStderr()); fixErr != nil {
361→		return fmt.Errorf("failed to reconcile metadata branches: %w", fixErr)
362→	}
363→
364→	fmt.Fprintln(w, "  ✓ Fixed: metadata branches reconciled")
365→	return nil
366→}
