368→// canDeleteShadowBranch checks if a shadow branch can be safely deleted.
369→// Returns true if no other sessions (besides excludeSessionID) need this branch.
370→func canDeleteShadowBranch(ctx context.Context, shadowBranch, excludeSessionID string) (bool, error) {
371→	states, err := strategy.ListSessionStates(ctx)
372→	if err != nil {
373→		return false, fmt.Errorf("failed to list session states: %w", err)
374→	}
375→
376→	for _, state := range states {
377→		if state.SessionID == excludeSessionID {
378→			continue
379→		}
380→		otherShadow := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
381→		if otherShadow == shadowBranch && state.StepCount > 0 {
382→			return false, nil
383→		}
384→	}
385→
386→	return true, nil
387→}
