268→	if err := os.WriteFile(filepath.Join(dir2, "metadata.json"), []byte(`{"checkpoint_id":"222222222222"}`), 0o644); err != nil {
269→		t.Fatalf("failed to write: %v", err)
270→	}
271→	run("add", ".")
272→	run("commit", "-m", "Checkpoint: 222222222222")
273→
274→	// Checkpoint 3
275→	dir3 := filepath.Join(cloneDir, "33", "3333333333")
276→	if err := os.MkdirAll(dir3, 0o755); err != nil {
277→		t.Fatalf("failed to create dir: %v", err)
278→	}
279→	if err := os.WriteFile(filepath.Join(dir3, "metadata.json"), []byte(`{"checkpoint_id":"333333333333"}`), 0o644); err != nil {
280→		t.Fatalf("failed to write: %v", err)
281→	}
282→	run("add", ".")
283→	run("commit", "-m", "Checkpoint: 333333333333")
284→
285→	run("branch", "-f", paths.MetadataBranchName, "temp-orphan")
286→	run("checkout", "main")
287→
288→	repo, err := git.PlainOpen(cloneDir)
289→	if err != nil {
290→		t.Fatalf("failed to open repo: %v", err)
291→	}
292→
293→	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
294→	remoteRef, err := repo.Reference(remoteRefName, true)
295→	if err != nil {
296→		t.Fatalf("remote ref not found: %v", err)
297→	}
298→
299→	// Run reconciliation
300→	if err := ReconcileDisconnectedMetadataBranch(context.Background(), repo, io.Discard); err != nil {
301→		t.Fatalf("ReconcileDisconnectedMetadataBranch() failed: %v", err)
302→	}
303→
304→	// Verify result
305→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
306→	newRef, err := repo.Reference(refName, true)
307→	if err != nil {
308→		t.Fatalf("local ref not found after reconcile: %v", err)
309→	}
310→
311→	// Walk commits to verify linear chain
312→	var commitMessages []string
313→	current := newRef.Hash()
314→	for range 10 {
315→		c, cErr := repo.CommitObject(current)
316→		if cErr != nil {
317→			t.Fatalf("failed to get commit %s: %v", current, cErr)
318→		}
319→		commitMessages = append(commitMessages, c.Message)
320→		if len(c.ParentHashes) == 0 {
321→			break
322→		}
323→		if len(c.ParentHashes) != 1 {
324→			t.Fatalf("expected linear history, commit %s has %d parents", c.Hash, len(c.ParentHashes))
325→		}
326→		current = c.ParentHashes[0]
327→	}
328→
329→	// Should have: 3 cherry-picked + remote commits (1 data + 1 root = at least 2)
330→	// The empty orphan commit is skipped, so we get exactly 3 cherry-picked commits
331→	if len(commitMessages) < 4 {
332→		t.Errorf("expected at least 4 commits in chain, got %d: %v", len(commitMessages), commitMessages)
333→	}
334→
335→	// Verify all checkpoint data is in the final tree
336→	tipCommit, err := repo.CommitObject(newRef.Hash())
337→	if err != nil {
338→		t.Fatalf("failed to get tip: %v", err)
339→	}
340→	tree, err := tipCommit.Tree()
341→	if err != nil {
342→		t.Fatalf("failed to get tree: %v", err)
343→	}
344→
345→	entries := make(map[string]object.TreeEntry)
346→	if err := checkpoint.FlattenTree(repo, tree, "", entries); err != nil {
347→		t.Fatalf("failed to flatten tree: %v", err)
348→	}
349→
350→	expectedPaths := []string{
351→		"metadata.json",               // Remote data
352→		"11/1111111111/metadata.json", // Checkpoint 1
353→		"22/2222222222/metadata.json", // Checkpoint 2
354→		"33/3333333333/metadata.json", // Checkpoint 3
355→	}
356→	for _, p := range expectedPaths {
357→		if _, ok := entries[p]; !ok {
358→			t.Errorf("merged tree missing expected path: %s", p)
359→		}
360→	}
361→
362→	// First cherry-picked commit's parent should be the remote tip
363→	// Walk back from tip: tip (cp3) -> cp2 -> cp1 -> remote tip
364→	cp3, err := repo.CommitObject(newRef.Hash())
365→	if err != nil {
366→		t.Fatalf("failed to get cp3: %v", err)
367→	}
368→	cp2, err := repo.CommitObject(cp3.ParentHashes[0])
369→	if err != nil {
370→		t.Fatalf("failed to get cp2: %v", err)
371→	}
372→	cp1, err := repo.CommitObject(cp2.ParentHashes[0])
373→	if err != nil {
374→		t.Fatalf("failed to get cp1: %v", err)
375→	}
376→	if cp1.ParentHashes[0] != remoteRef.Hash() {
377→		t.Errorf("first cherry-picked commit parent = %s, want remote tip %s",
378→			cp1.ParentHashes[0], remoteRef.Hash())
379→	}
380→}
