	run("commit", "-m", "local checkpoint")
	run("checkout", "main")

	// Re-open to see updated refs
	repo, err = git.PlainOpen(cloneDir)
	if err != nil {
		t.Fatalf("failed to re-open repo: %v", err)
	}

	// Shared ancestry → no-op
